/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimInventDimId_Product extends GUPPricingAttributeInventDim_Product implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventDimId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventDimId from inventDim
        group by InventDimId
    {
        ret.add(inventDim.InventDimId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventDimId));
    qbr.value(queryValue(_value));
}
